CREATE TABLE anon.events (event_id UInt64 CODEC(Delta, ZSTD(3)), event_time DateTime64(3) DEFAULT now64(3) CODEC(DoubleDelta), first_name String, last_name String, full_name String ALIAS concat(first_name,' ',last_name), name_length UInt32 MATERIALIZED lengthUTF8(first_name), raw_payload String EPHEMERAL, comment_text String DEFAULT '' COMMENT 'free text') ENGINE=ReplacingMergeTree(event_time) PARTITION BY toYYYYMM(event_time) ORDER BY event_id SETTINGS index_granularity=8192 COMMENT 'events table'